package com.smartsociety.platform.complaint; import com.smartsociety.platform.security.SecurityUser; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/complaints") public class ComplaintController {final ComplaintService s;public ComplaintController(ComplaintService x){s=x;}@PostMapping public ComplaintDtos.ComplaintResponse create(@Valid @RequestBody ComplaintDtos.CreateRequest r,@AuthenticationPrincipal SecurityUser u){return s.create(r,u);}@GetMapping public Page<ComplaintDtos.ComplaintResponse> list(@AuthenticationPrincipal SecurityUser u,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){return s.list(u,PageRequest.of(Math.min(page,100),Math.min(size,100),Sort.by("createdAt").descending()));}@GetMapping("/{id}") public ComplaintDtos.ComplaintResponse get(@PathVariable UUID id,@AuthenticationPrincipal SecurityUser u){return s.get(id,u);}@GetMapping("/{id}/history") public List<ComplaintDtos.HistoryResponse> history(@PathVariable UUID id,@AuthenticationPrincipal SecurityUser u){return s.history(id,u);} }
